// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 numPlays) public {
        vm.assume(numPlays >= 1 && numPlays <= 20);
        address player = address(0x1234);
        vm.deal(player, numPlays * 10 ether);
        vm.startPrank(player);
        bool payoutOccurred = false;
        for (uint i = 0; i < numPlays; i++) {
            uint prevPot = c.pot();
            c.play{value: 10}();
            if (c.pot() < prevPot) {
                payoutOccurred = true;
            }
        }
        vm.stopPrank();
        if (!payoutOccurred) {
            assertTrue(c.pot() > 0);
        }
    }
}
